module TopModule (
  input clk,
  input x,
  output reg z
);

reg d0, d1, d2;

// D flip-flops for storing the outputs of the gates
always @(posedge clk)
begin
    d0 <= x ^ d0;  // XOR gate
    d1 <= ~(x & d1);  // AND gate
    d2 <= ~(x | d2);  // OR gate
end

// Z output generated by a three-input NOR gate
assign z = ~(d0 | d1 | d2);

endmodule